"""Minimal standard-library client for OpenAI's Responses API.

The client avoids logging or persisting prompts. Set OPENAI_API_KEY in the
environment, then call send_private_prompt().
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Any, Mapping


DEFAULT_MODEL = "gpt-4.1-mini"
DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_TIMEOUT = 60.0


class OpenAIClientError(RuntimeError):
    """Base exception for this module."""


class OpenAIConfigurationError(OpenAIClientError):
    """Raised when the client cannot be configured."""


class OpenAIAPIError(OpenAIClientError):
    """Raised when the OpenAI API returns an error response."""

    def __init__(
        self,
        message: str,
        *,
        status: int | None = None,
        code: str | None = None,
        type: str | None = None,
    ) -> None:
        super().__init__(message)
        self.status = status
        self.code = code
        self.type = type


@dataclass(frozen=True)
class OpenAIResponse:
    """Parsed response returned by the Responses API."""

    id: str | None
    model: str | None
    output_text: str
    raw: Mapping[str, Any]


class OpenAIResponsesClient:
    """Small Responses API client using only Python's standard library."""

    def __init__(
        self,
        api_key: str | None = None,
        *,
        model: str = DEFAULT_MODEL,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float = DEFAULT_TIMEOUT,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIConfigurationError("Set OPENAI_API_KEY or pass api_key.")

        self.model = model
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def create_response(
        self,
        prompt: str,
        *,
        instructions: str | None = None,
        model: str | None = None,
        store: bool = False,
        temperature: float | None = None,
        max_output_tokens: int | None = None,
        extra_body: Mapping[str, Any] | None = None,
    ) -> OpenAIResponse:
        """Send a text prompt to the Responses API and return parsed output.

        Prompts and request bodies are not written to disk or included in raised
        exceptions. The API key is read from OPENAI_API_KEY unless passed to the
        constructor.
        """

        if not isinstance(prompt, str) or not prompt:
            raise ValueError("prompt must be a non-empty string")

        body: dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
            "store": store,
        }
        if instructions is not None:
            body["instructions"] = instructions
        if temperature is not None:
            body["temperature"] = temperature
        if max_output_tokens is not None:
            body["max_output_tokens"] = max_output_tokens
        if extra_body:
            body.update(extra_body)

        data = json.dumps(body).encode("utf-8")
        request = urllib.request.Request(
            f"{self.base_url}/responses",
            data=data,
            method="POST",
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
        )

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                payload = response.read().decode("utf-8")
        except urllib.error.HTTPError as exc:
            raise _api_error_from_http_error(exc) from exc
        except urllib.error.URLError as exc:
            raise OpenAIAPIError(f"Failed to reach OpenAI API: {exc.reason}") from exc
        except TimeoutError as exc:
            raise OpenAIAPIError("Timed out while calling OpenAI API.") from exc

        decoded = _decode_json(payload)
        if not isinstance(decoded, dict):
            raise OpenAIAPIError("OpenAI API returned an unexpected response.")

        return OpenAIResponse(
            id=_optional_str(decoded.get("id")),
            model=_optional_str(decoded.get("model")),
            output_text=_extract_output_text(decoded),
            raw=decoded,
        )


def send_private_prompt(
    prompt: str,
    *,
    api_key: str | None = None,
    model: str = DEFAULT_MODEL,
    instructions: str | None = None,
    timeout: float = DEFAULT_TIMEOUT,
    store: bool = False,
    temperature: float | None = None,
    max_output_tokens: int | None = None,
    extra_body: Mapping[str, Any] | None = None,
) -> str:
    """Send a private text prompt and return only the generated text."""

    client = OpenAIResponsesClient(api_key=api_key, model=model, timeout=timeout)
    response = client.create_response(
        prompt,
        instructions=instructions,
        store=store,
        temperature=temperature,
        max_output_tokens=max_output_tokens,
        extra_body=extra_body,
    )
    return response.output_text


def _api_error_from_http_error(exc: urllib.error.HTTPError) -> OpenAIAPIError:
    status = exc.code
    message = f"OpenAI API request failed with HTTP {status}."
    code = None
    error_type = None

    try:
        payload = exc.read().decode("utf-8")
    except Exception:
        payload = ""

    if payload:
        decoded = _decode_json(payload, default={})
        if isinstance(decoded, dict):
            error = decoded.get("error")
            if isinstance(error, dict):
                api_message = error.get("message")
                if isinstance(api_message, str) and api_message:
                    message = api_message
                code = _optional_str(error.get("code"))
                error_type = _optional_str(error.get("type"))

    return OpenAIAPIError(message, status=status, code=code, type=error_type)


def _decode_json(payload: str, default: Any = None) -> Any:
    try:
        return json.loads(payload)
    except json.JSONDecodeError as exc:
        if default is not None:
            return default
        raise OpenAIAPIError("OpenAI API returned invalid JSON.") from exc


def _extract_output_text(response: Mapping[str, Any]) -> str:
    direct = response.get("output_text")
    if isinstance(direct, str):
        return direct

    parts: list[str] = []
    output = response.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, Mapping):
                continue
            content = item.get("content")
            if not isinstance(content, list):
                continue
            for chunk in content:
                if isinstance(chunk, Mapping):
                    text = chunk.get("text")
                    if isinstance(text, str):
                        parts.append(text)

    return "".join(parts)


def _optional_str(value: Any) -> str | None:
    return value if isinstance(value, str) else None


if __name__ == "__main__":
    raise SystemExit(
        "Import this module and call send_private_prompt(prompt), "
        "or instantiate OpenAIResponsesClient."
    )
